!function(e){function r(r){for(var n,i,a=r[0],c=r[1],d=r[2],s=0,l=[];s<a.length;s++)i=a[s],Object.prototype.hasOwnProperty.call(p,i)&&p[i]&&l.push(p[i][0]),p[i]=0;for(n in c)Object.prototype.hasOwnProperty.call(c,n)&&(e[n]=c[n]);for(u&&u(r);l.length;)l.shift()();return o.push.apply(o,d||[]),t()}function t(){for(var e,r=0;r<o.length;r++){for(var t,i=o[r],a=!0,c=1;c<i.length;c++)t=i[c],0!==p[t]&&(a=!1);a&&(o.splice(r--,1),e=n(n.s=i[0]))}return e}function n(r){if(i[r])return i[r].exports;var t=i[r]={i:r,l:!1,exports:{}};return e[r].call(t.exports,t,t.exports,n),t.l=!0,t.exports}var i={},p={55:0},o=[];n.m=e,n.c=i,n.d=function(e,r,t){n.o(e,r)||Object.defineProperty(e,r,{enumerable:!0,get:t})},n.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},n.t=function(e,r){if(1&r&&(e=n(e)),8&r)return e;if(4&r&&"object"==typeof e&&e&&e.__esModule)return e;var t=Object.create(null);if(n.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:e}),2&r&&"string"!=typeof e)for(var i in e)n.d(t,i,function(r){return e[r]}.bind(null,i));return t},n.n=function(e){var r=e&&e.__esModule?function(){return e.default}:function(){return e};return n.d(r,"a",r),r},n.o=function(e,r){return Object.prototype.hasOwnProperty.call(e,r)},n.p="";var a=window.webpackJsonp=window.webpackJsonp||[],c=a.push.bind(a);a.push=r,a=a.slice();for(var d=0;d<a.length;d++)r(a[d]);var u=c;o.push([230,0]),t()}({230:function(e,r,t){"use strict";t.r(r);var n=t(0);Object(n.a)("de","army",t(231),t(1))},231:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"轻武器","link":"de_army#de_army_iw"}],"model":"德军反坦克枪","description":"<p>最早的反坦克枪是由德国研制并在一战中投入了实战，到了二战初期，反坦克枪仍是德军单兵携带的反坦克武器，使用的型号有PzB38型和PzB39型，但两者性能相差并不大。二战爆发德军闪击波兰，德国陆军就装备了568支PzB39型反坦克枪，1940年闪击西欧，德军发现PzB39型反坦克枪性能已经落后，而到了1941年入侵苏联，德军更是发现该枪已无法对付苏军的坦克，于是在1941年11月停止了生产，但生产了近4万支PzB39型反坦克枪怎么办？于是在1942年，德军对其进行了改装，换成了短枪管，并在枪口装上枪榴弹发射装置，变为一种榴弹发射步枪，型号改为GrB39，从而成为另一种有效的单兵作战武器。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_iwPzB_11.jpg","description":"<h6>PzB38/39型反坦克枪</h6><p></p><p>技术数据：</p><p>口径：7.92毫米；</p><p>枪身全长：1615/1581毫米，枪管长：1085毫米；</p><p>全枪重量（不含弹药盒）：16.2/11.6公斤；</p><p>枪口初速：1210米/秒；</p><p>子弹穿甲能力：100米距离可击穿30毫米厚垂直钢板/300米距离可击穿25毫米厚垂直钢板</p><p>子弹采用单发装填，射速：10发/分钟；枪管的最大后座距离：90毫米。</p>","caption":""},{"image":"imgs/de/army/de_army_iwPzB_12.jpg","description":"<h6>GrB39型榴弹发射步枪</h6><p>1942年，德军将PzB38/39型反坦克枪的枪管改短为590毫米，并在枪口装上枪榴弹发射装置，变为一种榴弹发射步枪，型号改为GrB39。</p><p>小图为该枪使用的枪榴弹。</p>","caption":""}],"part2title":"战场上的德军反坦克枪","part2description":"","part2content":[{"image":"imgs/de/army/de_army_iwPzB_21.jpg","description":"1940年，西线战场荷兰地区，一群全副武装的德军伞兵沿着荷兰的乡村小路前进，队伍中一人扛着PzB39型反坦克枪，由于战事顺利，士兵们都是开心轻松的表情。","caption":""},{"image":"imgs/de/army/de_army_iwPzB_22.jpg","description":"1941年8月，东线苏联战场，两名德军士兵伏在草丛中，架起了PzB39型反坦克枪，紧张地注视着前方，随时准备迎击苏军坦克。在“巴巴罗萨”行动时，德军一共装备有25000多支反坦克枪。","caption":""},{"image":"imgs/de/army/de_army_iwPzB_23.jpg","description":"二战初期，正在集合的德国武装党卫军第2“帝国”装甲师的一个排，其中一名士兵背负着一支PzB39型反坦克枪，在战争初期，反坦克枪在党卫队中还是比较稀有的武器装备。","caption":""},{"image":"imgs/de/army/de_army_iwPzB_24.jpg","description":"二战初期，两名持反坦克枪埋伏的德军士兵，士兵表情轻松，可能只是作一般的戒备，或是摆拍。实际上，这种反坦克枪已经落后，对付苏军的T-34坦克完全无效，只能在近距离对付一些轻型装甲车。","caption":""},{"image":"imgs/de/army/de_army_iwPzB_25.jpg","description":"一名手持PzB39型反坦克枪的德军士兵，图中可见挂在枪上的子弹盒已经打开。注：为了增加射速，PzB39型反坦克枪在进弹口两侧加装了一对子弹盒，每个子弹盒装弹十发，但这种子弹盒并不等同可进弹的弹夹，射击前，射手仍需用手从弹盒中取出子弹装进枪膛。但相比无弹夹的38型，装弹速度已提高不少。","caption":""}]}')}});